document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".auto-dismiss-alert").forEach(function(n){setTimeout(function(){var t=bootstrap.Alert.getOrCreateInstance(n);t.close()},4e3)});var n=document.querySelectorAll(".tag-filter");n.forEach(function(t){t.addEventListener("click",function(){n.forEach(function(n){n.classList.remove("js-active-preview")});t.classList.add("js-active-preview")})}),async function(){var t=document.getElementById("cartBadge"),i,n;if(t)try{i=await fetch("/Catalog/GetCartCount");n=await i.json();t.textContent=n.count>0?n.count:"0"}catch(r){console.error("Не удалось получить количество товаров в корзине:",r)}}()});